mapper.select:
SELECT r.*, o.wo_no, op.seq AS op_seq, op.name AS op_name, w.name AS work_center_name, u.nickname AS create_by_name, ou.nickname AS operator_name, eq.name AS equipment_name, md.code AS mold_code FROM mes_report r LEFT JOIN sys_user ou ON ou.id = r.operator_id LEFT JOIN mes_equipment eq ON eq.id = r.equipment_id LEFT JOIN mes_mold md ON md.id = r.mold_id JOIN mes_work_order o ON o.id = r.wo_id JOIN mes_wo_op op ON op.id = r.op_id LEFT JOIN mes_work_center w ON w.id = op.work_center_id LEFT JOIN sys_user u ON u.id = r.create_by
r.wo_id = #{woId} AND r.report_date >= #{beginDate} AND r.report_date <= #{endDate}
ORDER BY r.id DESC
